const UNAVAILABLE_PROFILE_VALUE_TOKENS = new Set([
  '-',
  'n/a',
  'na',
  'none',
  '无',
  '無',
]);

export const formatProfileOptionalValue = (
  value: string | undefined,
  fallback: string,
): string => {
  const normalizedValue = value?.trim();

  if (!normalizedValue) {
    return fallback;
  }

  if (UNAVAILABLE_PROFILE_VALUE_TOKENS.has(normalizedValue.toLowerCase())) {
    return fallback;
  }

  return normalizedValue;
};

